// ============================================================
// NODE CODE n8n — Enrichissement Prix Bitcoin
// ============================================================

const items = $input.all();

// ── 1. Extraction des prix ───────────────────────────────────
const prices = items
  .map(item => parseFloat(item.json["Prix (USD)"]))
  .filter(p => !isNaN(p) && p > 0);

const n = prices.length;

// ── 2. VARIATION 5 MIN ───────────────────────────────────────
const variation5min = n >= 2
  ? Math.round(((prices[n-1] - prices[n-2]) / prices[n-2]) * 100 * 10000) / 10000
  : null;

const variation1h = n >= 12
  ? Math.round(((prices[n-1] - prices[n-12]) / prices[n-12]) * 100 * 10000) / 10000
  : null;

// ── 3. EMA ───────────────────────────────────────────────────
function calcEMA(prices, periode) {
  if (prices.length < periode) return null;
  const k = 2 / (periode + 1);
  let ema = prices.slice(0, periode).reduce((a, b) => a + b, 0) / periode;
  for (let i = periode; i < prices.length; i++) {
    ema = prices[i] * k + ema * (1 - k);
  }
  return Math.round(ema * 100) / 100;
}

const ema12 = calcEMA(prices, 12);
const ema26 = calcEMA(prices, 26);

// ── 4. RSI 14 ────────────────────────────────────────────────
function calcRSI(prices, periode = 14) {
  if (prices.length < periode + 1) return null;
  const recent = prices.slice(-(periode + 1));
  let gains = 0, losses = 0;
  for (let i = 1; i < recent.length; i++) {
    const diff = recent[i] - recent[i - 1];
    if (diff > 0) gains += diff;
    else losses += Math.abs(diff);
  }
  const avgGain = gains / periode;
  const avgLoss = losses / periode;
  if (avgLoss === 0) return 100;
  return Math.round((100 - 100 / (1 + avgGain / avgLoss)) * 100) / 100;
}

const rsi = calcRSI(prices, 14);

// ── 5. Signaux ───────────────────────────────────────────────
const signalRSI = rsi === null ? "EN ATTENTE"
  : rsi >= 70 ? "⚠️ SURACHETÉ"
  : rsi <= 30 ? "🟢 SURVENDU"
  : rsi >= 55 ? "📈 Haussier"
  : rsi <= 45 ? "📉 Baissier"
  : "➡️ Neutre";

const signalMACD = (ema12 && ema26)
  ? (ema12 > ema26 ? "📈 HAUSSIER" : "📉 BAISSIER")
  : "EN ATTENTE";

// ── 6. Alerte ────────────────────────────────────────────────
const alertes = [];
if (rsi !== null && rsi >= 70) alertes.push("RSI SURACHETÉ (" + rsi + ")");
if (rsi !== null && rsi <= 30) alertes.push("RSI SURVENDU (" + rsi + ")");
if (variation5min !== null && Math.abs(variation5min) >= 1)
  alertes.push("VARIATION FORTE " + (variation5min > 0 ? "+" : "") + variation5min + "%");

// ── 7. Retour ────────────────────────────────────────────────
return [{
  json: {
    prix_actuel:        prices[n - 1],
    nb_points:          n,
    variation_5min_pct: variation5min,
    variation_1h_pct:   variation1h,
    ema_12:             ema12,
    ema_26:             ema26,
    signal_macd:        signalMACD,
    rsi_14:             rsi,
    signal_rsi:         signalRSI,
    alerte:             alertes.length > 0 ? alertes.join(" | ") : "Aucune alerte",
    timestamp:          new Date().toISOString()
  }
}];

