const position = staticData.openPosition;
const hasOpenPosition = !!position;
return [{json: {totalPnL: totalPnL.toFixed(2), winners, losers, totalTrades, winRate, avgPnL, bestTrade, worstTrade, hasOpenPosition, openPositionEntry: hasOpenPosition ? position.entryPrice : 0, openPositionQty: hasOpenPosition ? position.quantity : 0}}];

