const staticData = $getWorkflowStaticData('global');

const allPositions = staticData.closedPositions_A || [];
const now   = new Date();
const today = now.toISOString().slice(0, 10);
const heure = now.toLocaleString('fr-FR', { hour: '2-digit', minute: '2-digit' });
const isLastReport = now.getHours() >= 23;

const todayTrades = allPositions.filter(p => {
  const d = (p.exitTime || p.entryTime || '').slice(0, 10);
  return d === today;
});

function buildStats(trades) {
  if (!trades || trades.length === 0) return null;
  const wins     = trades.filter(p => parseFloat(p.pnlUsd) > 0);
  const losses   = trades.filter(p => parseFloat(p.pnlUsd) <= 0);
  const pnlTotal = trades.reduce((s, p) => s + parseFloat(p.pnlUsd), 0);
  const best     = Math.max(...trades.map(p => parseFloat(p.pnlUsd)));
  const worst    = Math.min(...trades.map(p => parseFloat(p.pnlUsd)));
  const wr       = (wins.length / trades.length * 100).toFixed(1);
  return { trades, wins: wins.length, losses: losses.length,
           total: trades.length, pnlTotal, wr, best, worst };
}

return [{ json: {
  statsDay:     buildStats(todayTrades),
  statsAll:     buildStats(allPositions),
  capital:      staticData.capital_A || 25,
  hasPos:       !!staticData.openPosition_A,
  openPos:      staticData.openPosition_A || null,
  today,
  heure,
  isLastReport
}}];

