const staticData = $getWorkflowStaticData('global');
const allPositions = staticData.closedPositions_A || [];
const now = new Date();

// Heure Paris (UTC+1 hiver, UTC+2 été)
const parisDiff = now.getTimezoneOffset(); // en minutes
const parisNow  = new Date(now.getTime() - parisDiff * 60000);
const today     = parisNow.toISOString().slice(0, 10); // "2026-02-22"
const heure     = parisNow.toISOString().slice(11, 16); // "11:00"
const isLastReport = parisNow.getUTCHours() >= 23;

// Filtre trades du jour — comparaison date locale
const todayTrades = allPositions.filter(p => {
  const raw = p.exitTime || p.entryTime || '';
  // Les dates sont stockées en ISO (ex: "2026-02-22T11:05:30.000Z")
  // On compare les 10 premiers caractères
  const tradeDate = raw.slice(0, 10);
  // Aussi essayer avec offset Paris
  const tradeTs   = new Date(raw);
  const tradeParis = new Date(tradeTs.getTime() - parisDiff * 60000);
  const tradeDateParis = tradeParis.toISOString().slice(0, 10);
  return tradeDate === today || tradeDateParis === today;
});

function stats(trades) {
  if (!trades || trades.length === 0) return null;
  const wins   = trades.filter(p => parseFloat(p.pnlUsd) > 0);
  const losses = trades.filter(p => parseFloat(p.pnlUsd) <= 0);
  const pnl    = trades.reduce((s, p) => s + parseFloat(p.pnlUsd), 0);
  return {
    trades,
    total:  trades.length,
    wins:   wins.length,
    losses: losses.length,
    wr:     (wins.length / trades.length * 100).toFixed(1),
    pnlTotal: pnl,
    best:   Math.max(...trades.map(p => parseFloat(p.pnlUsd))),
    worst:  Math.min(...trades.map(p => parseFloat(p.pnlUsd)))
  };
}

return [{ json: {
  statsDay: stats(todayTrades),
  statsAll: stats(allPositions),
  capital:  staticData.capital_A || 25,
  hasPos:   !!staticData.openPosition_A,
  openPos:  staticData.openPosition_A || null,
  today, heure, isLastReport,
  debug: {
    totalTrades: allPositions.length,
    todayCount:  todayTrades.length,
    serverTime:  now.toISOString(),
    parisTime:   parisNow.toISOString()
  }
}}];

