const rows = $input.all().map(i => i.json);

const now   = new Date();
const today = now.toISOString().slice(0, 10);
const heure = now.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });

// Séparer trades du jour vs cumulatif
const todayTrades = rows.filter(r => (r.exit_time || '').slice(0, 10) === today);
const allTrades   = rows;

function stats(trades) {
  if (!trades || trades.length === 0) return null;
  const wins   = trades.filter(t => parseFloat(t.pnl_usd) > 0);
  const losses = trades.filter(t => parseFloat(t.pnl_usd) <= 0);
  const pnl    = trades.reduce((s, t) => s + parseFloat(t.pnl_usd), 0);
  // Formater pour le rapport
  const formatted = trades.filter(t => (t.exit_time||'').slice(0,10) === today).map(t => ({
    direction:  t.direction,
    entryPrice: parseFloat(t.entry_price),
    exitPrice:  parseFloat(t.exit_price),
    pnlUsd:     parseFloat(t.pnl_usd),
