const staticData = $getWorkflowStaticData('global');

// Récupérer les trades depuis PostgreSQL (peut être vide)
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.exit_time); // filtrer les lignes vides

const now   = new Date();
// Timezone Paris
const offset = 60; // UTC+1 (hiver), ajuster à 120 en été
const parisNow = new Date(now.getTime() + offset * 60000);
const today = parisNow.toISOString().slice(0, 10);
const heure = parisNow.toISOString().slice(11, 16);
const isLastReport = parisNow.getUTCHours() >= 23;

// Trades du jour
const todayTrades = rows.filter(r => {
  const exitDate = new Date(r.exit_time);
  const exitParis = new Date(exitDate.getTime() + offset * 60000);
  return exitParis.toISOString().slice(0, 10) === today;
});

function stats(trades) {
  if (!trades || trades.length === 0) return null;
  const wins   = trades.filter(t => parseFloat(t.pnl_usd) > 0);
  const losses = trades.filter(t => parseFloat(t.pnl_usd) <= 0);
  const pnl    = trades.reduce((s, t) => s + parseFloat(t.pnl_usd), 0);
  const todayFormatted = todayTrades.map(t => ({
    direction:  t.direction,
    entryPrice: parseFloat(t.entry_price),
    exitPrice:  parseFloat(t.exit_price),
    pnlUsd:     parseFloat(t.pnl_usd),
    reason:     t.reason
  }));
  return {
    trades:   todayFormatted,
    total:    trades.length,
    wins:     wins.length,
    losses:   losses.length,
    wr:       (wins.length / trades.length * 100).toFixed(1),
    pnlTotal: pnl,
    best:     Math.max(...trades.map(t => parseFloat(t.pnl_usd))),
    worst:    Math.min(...trades.map(t => parseFloat(t.pnl_usd)))
  };
}

return [{ json: {
  statsDay:     stats(todayTrades),
  statsAll:     stats(rows),
  capital:      staticData.capital_A || 25,
  hasPos:       !!staticData.openPosition_A,
  openPos:      staticData.openPosition_A || null,
  today, heure, isLastReport,
  debug: { totalInDB: rows.length, todayCount: todayTrades.length }
}}];

