(function() {
  const s   = $json;
  const d   = s.statsDay;
  const a   = s.statsAll;
  const cap = parseFloat(s.capital).toFixed(2);

  const titre = s.isLastReport
    ? `📊 Strat A — Rapport FINAL | ${s.today}`
    : `⏱️ Strat A — Rapport ${s.heure} | ${s.today}`;

  let msg = `Bitcoin Alert Nkoy JM💰\n${titre}\n💼 Capital : $${cap}\n`;
  if (s.debug) msg += `_(${s.debug.todayCount} trades aujourd'hui / ${s.debug.totalInDB} en base)_\n`;
  msg += '\n';

  if (!d || d.total === 0) {
    msg += `😴 Aucun trade aujourd'hui\n`;
  } else {
    msg += `Trades du jour (${d.total}) :\n\`\`\`\n`;
    msg += `#  Dir    Entrée    Sortie    P&L\n`;
    msg += `───────────────────────────────────\n`;
    d.trades.forEach((t, i) => {
      const icon  = parseFloat(t.pnlUsd) > 0 ? '✅' : '❌';
      const dir   = t.direction === 'LONG' ? 'LONG ' : 'SHORT';
      const entry = ('$'+parseFloat(t.entryPrice).toFixed(0)).padStart(8);
      const exit  = ('$'+parseFloat(t.exitPrice).toFixed(0)).padStart(8);
      const pval  = parseFloat(t.pnlUsd);
      const pnl   = (pval >= 0 ? '+$' : '-$') + Math.abs(pval).toFixed(4);
      msg += `${(i+1).toString().padStart(2)} ${dir} ${entry} ${exit} ${pnl} ${icon}\n`;
    });
    msg += `\`\`\`\n`;
    const pday = parseFloat(d.pnlTotal);
    msg += `• WR  : ${d.wr}% (${d.wins} ✅ / ${d.losses} ❌)\n`;
    msg += `• P&L : ${pday >= 0 ? '+' : ''}$${pday.toFixed(4)}\n`;
    const best  = parseFloat(d.best);
    const worst = parseFloat(d.worst);
    msg += `• Best/Worst : +$${best.toFixed(4)} / ${worst < 0 ? '-' : '+'}$${Math.abs(worst).toFixed(4)}\n`;
  }

  if (s.hasPos && s.openPos) {
    const p = s.openPos;
    msg += `\n🔄 Position ouverte :\n`;
    msg += `• ${p.direction === 'BUY' ? 'LONG' : 'SHORT'} @ $${parseFloat(p.entryPrice).toFixed(2)}\n`;
    msg += `• TP $${parseFloat(p.tpPrice).toFixed(2)} | SL $${parseFloat(p.slPrice).toFixed(2)}\n`;
  } else {
    msg += `\n⏸️ Aucune position ouverte\n`;
  }

  if (s.isLastReport && a && a.total > 0) {
    const pall = parseFloat(a.pnlTotal);
    msg += `\n${'─'.repeat(33)}\n📈 Cumulatif depuis le début :\n`;
    msg += `• Trades : ${a.total} | WR : ${a.wr}%\n`;
    msg += `• P&L total : ${pall >= 0 ? '+' : ''}$${pall.toFixed(4)}\n`;
    msg += `• Capital : $${cap}\n`;
  }

  msg += `\n⏱️ ${new Date().toLocaleString('fr-FR')}\nAuto-rapport n8n`;
  return msg;
})()
}}

