// ============================================================================
// CLEANUP ZOMBIE POSITIONS - Complete Fixed Code for n8n v33
// ============================================================================
// Purpose: Detect and cleanup zombie positions every 1 minute
// Anti-spam: Only alert once per zombie, prevents repeated Telegram messages
// ============================================================================

const staticData = $getWorkflowStaticData('global');
const ZOMBIE_TIMEOUT = 20 * 60 * 1000; // 20 minutes timeout
const now = Date.now();

// ============================================================================
// SECTION 1: ANTI-SPAM CHECK
// ============================================================================
// If zombie already cleaned in last 60 seconds, skip to prevent spam alerts
const lastZombieCleanup = staticData.lastZombieCleanupTime_A || 0;
if (now - lastZombieCleanup < 60000) {
  // Already cleaned < 1 min ago, skip
  return [{ json: { 
    action: 'healthy', 
    positions_checked: 1,
    note: 'Zombie already cleaned recently, skipping'
  }}];
}

// ============================================================================
// SECTION 2: ZOMBIE DETECTION
// ============================================================================
let zombieInfo = null;

if (staticData.openPosition_A?.closing) {
  const lastClose = staticData.lastCloseTime_A || 0;

  // Check if position has been in "closing" state for too long
  if (now - lastClose > ZOMBIE_TIMEOUT) {
    // ============================================================================
    // SECTION 3: ZOMBIE FOUND - PREPARE CLEANUP INFO
    // ============================================================================
    zombieInfo = {
      cleared_at: new Date().toISOString(),
      position: {
        direction: staticData.openPosition_A.direction,
        entryPrice: staticData.openPosition_A.entryPrice,
        entryTime: staticData.openPosition_A.entryTime,
        tpPrice: staticData.openPosition_A.tpPrice,
        slPrice: staticData.openPosition_A.slPrice,
        quantity: staticData.openPosition_A.quantity
      },
      last_close_attempt: new Date(lastClose).toISOString(),
      time_since_crash_seconds: Math.round((now - lastClose) / 1000),
      reason: 'Zombie position not closed after 20 minutes'
    };

    // ============================================================================
    // SECTION 4: MARK AS CLEANED (Anti-spam)
    // ============================================================================
    // Set timestamp to prevent same zombie triggering alert multiple times
    staticData.lastZombieCleanupTime_A = now;

    // ============================================================================
    // SECTION 5: DELETE THE ZOMBIE POSITION
    // ============================================================================
    // Remove from memory to prevent future detection
    if (staticData.openPosition_A) {
      delete staticData.openPosition_A;
    }
  }
}

// ============================================================================
// SECTION 6: CONDITIONAL RETURN
// ============================================================================
// If zombie was found and cleaned, return cleanup info for Telegram + PostgreSQL
if (zombieInfo) {
  // Prepare data for PostgreSQL insert
  const dbInsertData = {
    position_data: JSON.stringify(zombieInfo.position),
    last_close_attempt_time: zombieInfo.last_close_attempt,
    time_since_crash_seconds: zombieInfo.time_since_crash_seconds,
    reason: zombieInfo.reason
  };

  // Return cleanup action
  return [{ json: { 
    action: 'zombie_cleanup',
    position: zombieInfo,
    timestamp: new Date().toISOString(),
    db_insert: dbInsertData
  }}];
} else {
  // No zombie detected, return healthy status
  return [{ json: { 
    action: 'healthy', 
    positions_checked: 1,
    timestamp: new Date().toISOString()
  }}];
}

// ============================================================================
// END OF CLEANUP ZOMBIE CODE
// ============================================================================

