// TRANSFORM KLINES - Single candle fix

const candle = $input.first().json;

// Binance format: [openTime, open, high, low, close, volume, closeTime, ...]
const close = parseFloat(candle[4]);
const high = parseFloat(candle[2]);
const low = parseFloat(candle[3]);
const open = parseFloat(candle[1]);
const volume = parseFloat(candle[5]);
const openTime = parseFloat(candle[0]);
const closeTime = parseFloat(candle[6]);

return [{
  json: {
    close: close,
    high: high,
    low: low,
    open: open,
    volume: volume,
    openTime: openTime,
    closeTime: closeTime
  }
}];

// ============================================================================
// CALCULATE INDICATORS — STRAT A v2 (EMA9/EMA21 + ATR + Pullback/Reprise)
// ============================================================================

const cur = $input.first().json;
const staticData = $getWorkflowStaticData('global');

// ============================================================================
// 1. EXTRACTION DES PRIX
// ============================================================================
const close = parseFloat(cur.close);
const high = parseFloat(cur.high);
const low  = parseFloat(cur.low);

// Historique des closes pour pullback/reprise
if (!staticData.prevClose_A) staticData.prevClose_A = close;
const prevClose = staticData.prevClose_A;
staticData.prevClose_A = close;

// ============================================================================
// 2. EMA9 & EMA21
// ============================================================================

function ema(prev, price, period) {
  const k = 2 / (period + 1);
  return prev === undefined ? price : (price * k + prev * (1 - k));
}

staticData.ema9_A  = ema(staticData.ema9_A,  close, 9);
staticData.ema21_A = ema(staticData.ema21_A, close, 21);

const ema9  = staticData.ema9_A;
const ema21 = staticData.ema21_A;

// ============================================================================
// 3. ATR(14)
// ============================================================================

const tr = Math.max(
  high - low,
  Math.abs(high - prevClose),
  Math.abs(low  - prevClose)
);

if (!staticData.atrList_A) staticData.atrList_A = [];
staticData.atrList_A.push(tr);
if (staticData.atrList_A.length > 14) staticData.atrList_A.shift();

const atr = staticData.atrList_A.reduce((a,b)=>a+b,0) / staticData.atrList_A.length;
const atrPct = (atr / close) * 100;

// ============================================================================
// 4. TENDANCE (EMA9 vs EMA21)
// ============================================================================
const trendUp   = ema9 > ema21;
const trendDown = ema9 < ema21;

// ============================================================================
// 5. PULLBACK + REPRISE
// ============================================================================

// Pullback long : prix repasse sous EMA9
const pullbackLong = prevClose < ema9;
// Reprise long : prix repasse au-dessus EMA9
const repriseLong  = close > ema9;

// Pullback short : prix repasse au-dessus EMA9
const pullbackShort = prevClose > ema9;
// Reprise short : prix repasse sous EMA9
const repriseShort  = close < ema9;

// ============================================================================
// 6. CONDITIONS D’ENTRÉE (SIGNAL v2)
// ============================================================================

const signal_long =
  trendUp &&
  pullbackLong &&
  repriseLong &&
  atrPct > 0.15;

const signal_short =
  trendDown &&
  pullbackShort &&
  repriseShort &&
  atrPct > 0.15;

// ============================================================================
// 7. TP/SL DYNAMIQUES (basés sur ATR)
// ============================================================================

const tp_long  = close + atr * 1.5;
const sl_long  = close - atr * 1.0;

const tp_short = close - atr * 1.5;
const sl_short = close + atr * 1.0;

// ============================================================================
// 8. RETOUR DES INDICATEURS
// ============================================================================

return [{
  json: {
    // Prix
    close,
    high,
    low,

    // EMA
    ema9: parseFloat(ema9.toFixed(2)),
    ema21: parseFloat(ema21.toFixed(2)),

    // ATR
    atr: parseFloat(atr.toFixed(4)),
    atrPct: parseFloat(atrPct.toFixed(3)),

    // Tendance
    trendUp,
    trendDown,

    // Pullback / Reprise
    pullbackLong,
    repriseLong,
    pullbackShort,
    repriseShort,

    // Signaux
    signal_long,
    signal_short,

    // TP/SL dynamiques
    tp_long: parseFloat(tp_long.toFixed(2)),
    sl_long: parseFloat(sl_long.toFixed(2)),
    tp_short: parseFloat(tp_short.toFixed(2)),
    sl_short: parseFloat(sl_short.toFixed(2)),

    // Timestamp
    timestamp: new Date().toISOString()
  }
}];

// ============================================================================
// ENTRY SIGNAL v2 — Étanche, robuste, basé sur Calculate Indicators v2
// ============================================================================

// Récupération sécurisée des items
const items = $input.all();
if (!items || items.length === 0) {
  return [];   // Aucun item → aucune entrée possible
}

const d = items[0].json;
const staticData = $getWorkflowStaticData('global');

// ============================================================================
// 1. BLOQUER SI UNE POSITION EST DÉJÀ OUVERTE
// ============================================================================
if (staticData.openPosition_A && staticData.openPosition_A.status === 'OPEN') {
  return [];   // Position déjà ouverte → aucune entrée
}

// ============================================================================
// 2. VALIDATION DES DONNÉES (sécurité anti-items fantômes)
// ============================================================================
if (
  d.close === undefined ||
  d.ema9 === undefined ||
  d.ema21 === undefined ||
  d.atr === undefined ||
  d.atrPct === undefined
) {
  return [];   // Données incomplètes → aucune entrée
}

// ============================================================================
// 3. CONDITIONS D’ENTRÉE (SIGNAL v2)
// ============================================================================

const signalLong  = d.signal_long  === true;
const signalShort = d.signal_short === true;

// Si aucun signal valide → bloquer
if (!signalLong && !signalShort) {
  return [];
}

// ============================================================================
// 4. ENTRÉE VALIDÉE → transmettre l’item complet
// ============================================================================
return items;

// ============================================================================
// EXIT CONDITIONS v2 — TP/SL dynamiques + signal inverse + ATR collapse
// ============================================================================

const staticData = $getWorkflowStaticData('global');
const pos = staticData.openPosition_A;

// ============================================================================
// 1. SÉCURITÉ : AUCUNE POSITION OUVERTE
// ============================================================================
if (!pos || pos.status !== "OPEN") {
  return [{ json: { shouldClose: false, reason: "no-open-position" }}];
}

// ============================================================================
// 2. RÉCUPÉRATION DES INDICATEURS ACTUELS
// ============================================================================
const ind = $input.first().json;

if (!ind || ind.close === undefined) {
  return [{ json: { shouldClose: false, reason: "invalid-indicators" }}];
}

const price = parseFloat(ind.close);
const ema9  = parseFloat(ind.ema9);
const ema21 = parseFloat(ind.ema21);
const atrPct = parseFloat(ind.atrPct);

// ============================================================================
// 3. RÉCUPÉRATION DES NIVEAUX TP/SL
// ============================================================================
const tp = parseFloat(pos.tpPrice);
const sl = parseFloat(pos.slPrice);

// ============================================================================
// 4. LOGIQUE DE SORTIE
// ============================================================================

let shouldClose = false;
let reason = "";

// Direction de la position
const isLong = pos.direction === "BUY";
const isShort = pos.direction === "SELL";

// ---------------------------------------------------------------------------
// A) TP / SL
// ---------------------------------------------------------------------------

if (isLong) {
  if (price >= tp) { shouldClose = true; reason = "tp-hit"; }
  if (price <= sl) { shouldClose = true; reason = "sl-hit"; }
}

if (isShort) {
  if (price <= tp) { shouldClose = true; reason = "tp-hit"; }
  if (price >= sl) { shouldClose = true; reason = "sl-hit"; }
}

// ---------------------------------------------------------------------------
// B) Signal inverse (croisement EMA9/EMA21)
// ---------------------------------------------------------------------------

if (!shouldClose) {
  if (isLong && ema9 < ema21) {
    shouldClose = true;
    reason = "trend-reversal";
  }
  if (isShort && ema9 > ema21) {
    shouldClose = true;
    reason = "trend-reversal";
  }
}

// ---------------------------------------------------------------------------
// C) ATR collapse (volatilité trop faible → trade inutile)
// ---------------------------------------------------------------------------

if (!shouldClose && atrPct < 0.08) {
  shouldClose = true;
  reason = "atr-collapse";
}

// ============================================================================
// 5. MARQUER LA POSITION COMME EN FERMETURE (ZOMBIE PROTECTION)
// ============================================================================
if (shouldClose) {
  staticData.openPosition_A.closing = true;
  staticData.lastCloseTime_A = Date.now();
}

// ============================================================================
// 6. RETOUR
// ============================================================================
return [{
  json: {
    shouldClose,
    reason,
    price,
    tp,
    sl,
    ema9,
    ema21,
    atrPct,
    direction: pos.direction,
    entryPrice: pos.entryPrice
  }
}];

// ============================================================================
// CLOSE POSITION v2 — propre, robuste, cohérent avec Strat A v2
// ============================================================================

const staticData = $getWorkflowStaticData('global');
const pos = staticData.openPosition_A;
const order = $input.first().json;

// ============================================================================
// 1. SÉCURITÉ : AUCUNE POSITION OUVERTE
// ============================================================================
if (!pos || pos.status !== "OPEN") {
  return [{
    json: {
      closed: false,
      reason: "no-open-position"
    }
  }];
}

// ============================================================================
// 2. EXTRACTION DU PRIX DE SORTIE
// ============================================================================
const exitPrice = parseFloat(order.fills?.[0]?.price);
if (isNaN(exitPrice)) {
  return [{
    json: {
      closed: false,
      reason: "invalid-exit-price"
    }
  }];
}

// ============================================================================
// 3. EXTRACTION DES DONNÉES DE LA POSITION
// ============================================================================
const entryPrice = parseFloat(pos.entryPrice);
const qty = parseFloat(pos.quantity);
const isLong = pos.direction === "BUY";
const isShort = pos.direction === "SELL";

// ============================================================================
// 4. CALCUL DU PnL
// ============================================================================

// PnL USD
let pnl_usd = 0;
if (isLong) {
  pnl_usd = (exitPrice - entryPrice) * qty;
} else {
  pnl_usd = (entryPrice - exitPrice) * qty;
}

// PnL %
let pnl_pct = 0;
if (isLong) {
  pnl_pct = ((exitPrice - entryPrice) / entryPrice) * 100;
} else {
  pnl_pct = ((entryPrice - exitPrice) / entryPrice) * 100;
}

// ============================================================================
// 5. MISE À JOUR DU CAPITAL
// ============================================================================
if (!staticData.capital_A) staticData.capital_A = 0;
staticData.capital_A = parseFloat(staticData.capital_A) + pnl_usd;

// ============================================================================
// 6. MARQUER LA POSITION COMME FERMÉE
// ============================================================================
staticData.openPosition_A.status = "CLOSED";
staticData.openPosition_A.exitPrice = exitPrice;
staticData.openPosition_A.exitTime = new Date().toISOString();
staticData.openPosition_A.pnl_usd = pnl_usd;
staticData.openPosition_A.pnl_pct = pnl_pct;

// ============================================================================
// 7. SUPPRESSION DE LA POSITION (FIN PROPRE)
// ============================================================================
delete staticData.openPosition_A;

// ============================================================================
// 8. RETOUR POUR NOTIFY SELL + PostgreSQL
// ============================================================================
return [{
  json: {
    closed: true,
    orderId: order.orderId,
    direction: pos.direction,
    entryPrice,
    exitPrice,
    qty,
    pnl_usd: parseFloat(pnl_usd.toFixed(6)),
    pnl_pct: parseFloat(pnl_pct.toFixed(4)),
    capital_after: parseFloat(staticData.capital_A.toFixed(2)),
    exitTime: new Date().toISOString(),
    strategie: "A"
  }
}];

