/*Name: Calculate 1H Indicators
Type: Code Node (JavaScript)

Purpose: Calculate EMA(9), EMA(26) on 1H candles
- These are used for TREND CONFIRMATION
- EMA(9) > EMA(26) = Uptrend
- EMA(9) < EMA(26) = Downtrend

Code:
*/
const candles = $input.all();
const closes = candles.map(c => parseFloat(c.json.close));

// EMA calculation
const ema = (data, period) => {
  const k = 2 / (period + 1);
  let ema = data[0];
  for (let i = 1; i < data.length; i++) {
    ema = data[i] * k + ema * (1 - k);
  }
  return ema;
};

const ema9_1h = ema(closes, 9);
const ema26_1h = ema(closes, 26);

return [{
  json: {
    ema9_1h: parseFloat(ema9_1h.toFixed(2)),
    ema26_1h: parseFloat(ema26_1h.toFixed(2)),
    trendUp: ema9_1h > ema26_1h,
    trendDown: ema9_1h < ema26_1h
  }
}];

// ============================================================================
// CALCULATE 5M INDICATORS - COMPLETE & WORKING
// Purpose: Calculate EMA(9), RSI(14), ATR(14) on 5M data
// ============================================================================

const staticData = $getWorkflowStaticData('global');

// ============================================================================
// SECTION 1: GET INPUT DATA
// ============================================================================

const items = $input.all();

if (!items || items.length === 0) {
  return [{
    json: {
      error: 'No 5M data available',
      prix_actuel: 0,
      rsi_14: 50,
      atr: 0,
      atrPercent: 0,
      ema9: 0
    }
