const lows = items.map(item => parseFloat(item.json.low));
const opens = items.map(item => parseFloat(item.json.open));

const currentPrice = closes[closes.length - 1];

// ============================================================================
// SECTION 2: EMA CALCULATION (9-period)
// ============================================================================

const emaCalculate = (data, period) => {
  if (data.length < period) {
    return data[data.length - 1];  // Return last price if not enough data
  }

  const k = 2 / (period + 1);
  let emaValue = data[0];

  for (let i = 1; i < data.length; i++) {
    emaValue = data[i] * k + emaValue * (1 - k);
  }

  return emaValue;
};

const ema9 = emaCalculate(closes, 9);

// ============================================================================
// SECTION 3: RSI CALCULATION (14-period)
// ============================================================================

const rsiCalculate = (closes, period = 14) => {
  if (closes.length < period + 1) {
    return 50;  // Default to 50 if not enough data
  }

  let gains = 0;
  let losses = 0;

  for (let i = 1; i <= period; i++) {
    const change = closes[closes.length - i] - closes[closes.length - i - 1];

    if (change > 0) {
      gains += change;
    } else {
      losses += Math.abs(change);
    }
  }

  const avgGain = gains / period;
  const avgLoss = losses / period;

  if (avgLoss === 0) {
    return avgGain > 0 ? 100 : 50;
  }

  const rs = avgGain / avgLoss;
  const rsi = 100 - (100 / (1 + rs));

  return rsi;
};

const rsi14 = rsiCalculate(closes, 14);

// ============================================================================
// SECTION 4: ATR CALCULATION (14-period)
// ============================================================================

const atrCalculate = (highs, lows, closes, period = 14) => {
  if (closes.length < period + 1) {
    return 0;  // Not enough data
  }

  let trueRanges = [];

  for (let i = 1; i < closes.length; i++) {
    const highLow = highs[i] - lows[i];
    const highClose = Math.abs(highs[i] - closes[i - 1]);
    const lowClose = Math.abs(lows[i] - closes[i - 1]);

    const trueRange = Math.max(highLow, highClose, lowClose);
    trueRanges.push(trueRange);
  }

  // Calculate average of last 14 TR values
  const recentTR = trueRanges.slice(-period);
  const atr = recentTR.reduce((a, b) => a + b, 0) / period;

  return atr;
};

const atr = atrCalculate(highs, lows, closes, 14);
const atrPercent = currentPrice > 0 ? (atr / currentPrice) * 100 : 0;

