if (!items || items.length === 0) return [{ json: { error: 'No 5M data', prix_actuel: 0, rsi_14: 50, atr: 0, atrPercent: 0, ema9: 0 } }];
const closes = items.map(item => parseFloat(item.json.close));
const highs = items.map(item => parseFloat(item.json.high));
const lows = items.map(item => parseFloat(item.json.low));
const currentPrice = closes[closes.length - 1];
const emaCalculate = (data, period) => {
  if (data.length < period) return data[data.length - 1];
  const k = 2 / (period + 1);
  let emaValue = data[0];
  for (let i = 1; i < data.length; i++) emaValue = data[i] * k + emaValue * (1 - k);
  return emaValue;
};
const rsiCalculate = (closes, period = 14) => {
  if (closes.length < period + 1) return 50;
  let gains = 0, losses = 0;
  for (let i = 1; i <= period; i++) {
    const change = closes[closes.length - i] - closes[closes.length - i - 1];
    if (change > 0) gains += change;
    else losses += Math.abs(change);
  }
  const avgGain = gains / period, avgLoss = losses / period;
  if (avgLoss === 0) return avgGain > 0 ? 100 : 50;
  const rs = avgGain / avgLoss;
  return 100 - (100 / (1 + rs));
};
const atrCalculate = (highs, lows, closes, period = 14) => {
  if (closes.length < period + 1) return 0;
  let trueRanges = [];
  for (let i = 1; i < closes.length; i++) {
    const tr = Math.max(highs[i] - lows[i], Math.abs(highs[i] - closes[i-1]), Math.abs(lows[i] - closes[i-1]));
    trueRanges.push(tr);
  }
  const recentTR = trueRanges.slice(-period);
  return recentTR.reduce((a,b) => a+b, 0) / period;
};
const ema9 = emaCalculate(closes, 9);
const rsi14 = rsiCalculate(closes, 14);
const atr = atrCalculate(highs, lows, closes, 14);
