const tpPrice = parseFloat(pos.tpPrice);
const slPrice = parseFloat(pos.slPrice);
const isBuy = pos.direction === 'BUY' || pos.direction === 'LONG';

let shouldClose = false;
let reason = '';

// 1. TP HIT
if (isBuy && currentPrice >= tpPrice) {
  shouldClose = true;
  reason = 'TP atteint';
} else if (!isBuy && currentPrice <= tpPrice) {
  shouldClose = true;
  reason = 'TP atteint';
}

// 2. SL HIT
if (!shouldClose) {
  if (isBuy && currentPrice <= slPrice) {
    shouldClose = true;
    reason = 'SL touche';
  } else if (!isBuy && currentPrice >= slPrice) {
    shouldClose = true;
    reason = 'SL touche';
  }
}

// 3. TIMEOUT
if (!shouldClose) {
  const entryTimeMs = new Date(pos.entryTime).getTime();
  const nowMs = Date.now();
  const elapsedMs = nowMs - entryTimeMs;
  const timeoutMs = 15 * 60 * 1000;

  if (elapsedMs > timeoutMs) {
