    status: result.status
  }
}];

const pos = $node['Check if Position Exists'].json;
const priceData = $input.first().json;

if (!pos || !pos.order_id) {
  return [];
}

const currentPrice = parseFloat(priceData.price);
const entryPrice = pos.entry_price;
const tpPrice = pos.tp_price;
const slPrice = pos.sl_price;
const isBuy = pos.direction === 'BUY' || pos.direction === 'LONG';

let shouldClose = false;
let reason = '';

if (isBuy && currentPrice >= tpPrice) {
  shouldClose = true;
  reason = 'TP atteint';
} else if (!isBuy && currentPrice <= tpPrice) {
  shouldClose = true;
  reason = 'TP atteint';
}

if (!shouldClose) {
  if (isBuy && currentPrice <= slPrice) {
    shouldClose = true;
    reason = 'SL touche';
  } else if (!isBuy && currentPrice >= slPrice) {
    shouldClose = true;
    reason = 'SL touche';
  }
}

if (!shouldClose) {
  const entryTimeMs = new Date(pos.entry_time).getTime();
  const nowMs = Date.now();
  const elapsedMs = nowMs - entryTimeMs;
  const timeoutMs = 45 * 60 * 1000;

  if (elapsedMs > timeoutMs) {
    shouldClose = true;
    reason = 'Zombie timeout 45min';
  }
}

return [{
  json: {
    shouldClose: shouldClose,
    reason: reason,
    currentPrice: currentPrice,
    entryPrice: entryPrice,
    tpPrice: tpPrice,
    slPrice: slPrice,
    direction: pos.direction,
    orderId: pos.order_id,
    quantity: pos.quantity,
    positionId: pos.id,
    status: shouldClose ? 'CLOSE_TRIGGERED' : 'MONITORING'
  }
}];

const exitData = $input.first().json;

const entryPrice = parseFloat(exitData.entryPrice);
const exitPrice = parseFloat(exitData.currentPrice);
const quantity = parseFloat(exitData.quantity);
const direction = exitData.direction;

let pnlAmount = 0;
if (direction === 'BUY' || direction === 'LONG') {
  pnlAmount = (exitPrice - entryPrice) * quantity;
} else {
  pnlAmount = (entryPrice - exitPrice) * quantity;
}

const pnlPercent = ((exitPrice - entryPrice) / entryPrice) * 100;

return [{
  json: {
    orderId: exitData.orderId,
    positionId: exitData.positionId,
