const slPrice = pos.sl_price;
const isBuy = pos.direction === 'BUY' || pos.direction === 'LONG';

let shouldClose = false;
let reason = '';

if (isBuy && currentPrice >= tpPrice) {
  shouldClose = true;
  reason = 'TP atteint';
} else if (!isBuy && currentPrice <= tpPrice) {
  shouldClose = true;
  reason = 'TP atteint';
}

if (!shouldClose) {
  if (isBuy && currentPrice <= slPrice) {
    shouldClose = true;
    reason = 'SL touche';
  } else if (!isBuy && currentPrice >= slPrice) {
    shouldClose = true;
    reason = 'SL touche';
  }
}

