  //const entryTimeMs = new Date(pos.entry_time).getTime();
  const entryTimeMs = new Date(pos.entry_time + 'Z').getTime();
  const nowMs = Date.now();
  const elapsedMs = nowMs - entryTimeMs;
  const timeoutMs = 45 * 60 * 1000;

  if (elapsedMs > timeoutMs) {
    shouldClose = true;
    reason = 'Zombie timeout 45min';
  }
}

