console.log('Capital :', capital);
console.log('Risque (%) :', riskPct * 100);
console.log('Perte max autorisée :', maxLoss);
console.log('Entry :', entry);
console.log('SL :', sl);
console.log('Distance SL :', slDistance);
console.log('Quantité calculée :', qty);
console.log('Valeur position :', positionValue);
console.log('Levier calculé :', leverage);

const montantUSDT = parseFloat((qty * entry).toFixed(2));

return [{
